insert into public.competencies (code,title,description,sequence,status) values ('R1','Pulse & Beat','Feel and recognize pulse and beat.',1,'active'),('R2','Tempo','Understand and recognize tempo.',2,'active'),('R3','Meter','Understand and recognize meter.',3,'active'),('R4','Note Value, Rest & Rhythm Composer','Construct rhythm using note values and rests.',4,'active'),('R5','Rhythm Reading','Read rhythmic patterns.',5,'active'),('R6','Rhythm Analysis','Analyze rhythmic structure.',6,'active'),('R7','Rhythm Performance','Perform rhythmic patterns.',7,'active'),('R8','Rhythm Creation','Create original rhythmic compositions.',8,'active') on conflict (code) do update set title=excluded.title,description=excluded.description,sequence=excluded.sequence,status=excluded.status;;
